def solve_math_problem(n: int, modulus: int, divisor: int) -> str:
    """
    Calculates the last two digits of a_n based on the defined recurrence relation.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer.")

    a_k: int = 0
    for k in range(1, n + 1):
        if k % divisor == 0:
            a_k = (a_k * k) % modulus
        else:
            a_k = (a_k + k) % modulus

    return f"{a_k:02d}"
